SELECT  json_build_object('nodes', coalesce(json_agg("root.f.nodes" ORDER BY "root.pg.id" DESC NULLS FIRST), '[]' ) ) AS "root" FROM  (SELECT  row_to_json((SELECT  "_e"  FROM  (SELECT  "_root.base"."id" AS "id", "_root.base"."name" AS "name"       ) AS "_e"      ) ) AS "root.f.nodes", "_root.base"."id" AS "root.pg.id" FROM  (SELECT  *  FROM "public"."author"  WHERE ('true')   ORDER BY "id" DESC NULLS FIRST LIMIT 2 ) AS "_root.base"    ORDER BY "root.pg.id" DESC NULLS FIRST  ) AS "_root"      
